-- ---------------------------------------------------------------------------
-- Progression content: the level ladder, shells, rooms, portals and Endeavors.
--
-- Every realm-owned id in this file is 0 and carries the name to search for.
-- tools/sql/bind_housing_content.sql fills them from the realm's own tables and
-- reports what it could not find; nothing here is a number typed from memory.
-- ---------------------------------------------------------------------------

DELETE FROM `housing_house_level`;

DELETE FROM `housing_shell` WHERE `id` BETWEEN 1 AND 12;

DELETE FROM `housing_room` WHERE `id` BETWEEN 1 AND 32;

-- shell_id 0 on a room means every shell has it. A room is a shape and a footprint:
-- cells_x by cells_y four-yard cells on the house floorplan, which is what the server
-- checks when the room is placed. A room with `stairs` 1 is how a house reaches the
-- floor above it, and the three stairwells are the only shapes that carry it.

DELETE FROM `housing_portal` WHERE `id` BETWEEN 1 AND 32;

DELETE FROM `housing_endeavor` WHERE `id` BETWEEN 1 AND 12;

DELETE FROM `housing_endeavor_task` WHERE `id` BETWEEN 1 AND 128;

DELETE FROM `housing_endeavor_reward` WHERE `endeavor_id` BETWEEN 1 AND 12;

-- Rewards pay XP and Community Coupons (3363, a real 8.3.7 currency). No item is
-- granted: an item id belongs to the realm's item_template, and no decor piece needs
-- one when the catalogue is the reward. The milestone is what unlocks vendor stock
-- up to that step (housing_vendor_stock.milestone).

DELETE FROM `housing_dye`;

DELETE FROM `housing_decor_creature` WHERE `decor_id` >= 1000;

-- 4 pet bed(s): a bed with no default creature, because the companion is the
-- player's and a default would put a cat in every cage.

-- kind 0 pet bed, 1 mount stand, 2 mannequin. Only kind 0 is shipped: a mount stand
-- and a mannequin need the owner's chosen mount or transmog, and those flags are
-- reserved until something reads them.

